function MetricsCard({ points }: { points: number[] }) {
  const ref = useRef<HTMLDivElement>(null);
  const [total, setTotal] = useState(0);

  // effect 1: render the non-React chart
  useEffect(() => {
    const chart = createChart(ref.current!, points);
    // no cleanup
  }, [points]);

  // effect 2: keep the total in sync
  useEffect(() => {
    setTotal(points.reduce((a, b) => a + b, 0));
  }, [points]);

  return (
    <div>
      <div ref={ref} />
      <p>Total: {total.toLocaleString()}</p>
    </div>
  );
}
